  ['pivot']: 'tappi',
  ['heart cam · r 3.36 → rMin 1.08 (0.32 r)']: 'epäkesko · r 3.36 → rMin 1.08 (0.32 r)',
  ['r(θ) = rMin + (r − rMin)(1 − cos θ)/2']: 'r(θ) = rMin + (r − rMin)(1 − cos θ)/2',
  ['lever arm 7.73 · roller ⌀ 1.4']: 'vipuvarsi 7.73 · rulla ⌀ 1.4',
